import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Auth = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const isFormValid = email.trim() !== '' && password.trim() !== '';

  const handleGetCode = (e) => {
    e.preventDefault();
    if (!isFormValid) return;
    // TODO: запрос к backend за кодом подтверждения
    // TODO: navigate('/code')
  };

  return (
    <div className="flex min-h-[100dvh] w-full flex-col overflow-hidden bg-secondary px-5 py-4">
      <div className="mx-auto flex w-full max-w-[480px] flex-1 flex-col">

        {/* Градиент в потоке — занимает своё место, контент идёт ниже */}
        <div className="flex items-center justify-center">
          <div
            aria-hidden
            className="pointer-events-none h-[120px] w-[200px] rotate-[-20deg] sm:h-[170px] sm:w-[260px]"
            style={{
              background:
                'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
            }}
          />
        </div>

        {/* Заголовок */}
        <header className="mt-3 sm:mt-6">
          <h1 className="text-[32px] leading-[105%] font-semibold text-black sm:text-[40px] laptop:text-[64px] desktop:text-[32px]">
            Вход
          </h1>
          <p className="mt-1.5 text-[13px] leading-[120%] text-gray sm:mt-2 sm:text-[14px] laptop:text-[20px] desktop:text-[14px] desktop:font-medium">
            Введите данные аккаунта, чтобы получить код для входа
          </p>
        </header>

        {/* Форма */}
        <form onSubmit={handleGetCode} noValidate className="mt-6 flex flex-col gap-4 sm:mt-8 sm:gap-5">
          {/* Email */}
          <input
            type="email"
            placeholder="email.vsk@gmail.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="h-11 w-full bg-transparent text-[15px] text-black placeholder-gray
                       focus:outline-none sm:h-12 sm:text-[16px] laptop:text-[20px] desktop:text-[14px]"
          />

          {/* Пароль */}
          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="Пароль"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="h-11 w-full bg-transparent pr-12 text-[15px] text-black placeholder-gray
                         focus:outline-none sm:h-12 sm:text-[16px] laptop:text-[20px] desktop:text-[14px]"
            />
            <button
              type="button"
              aria-label={showPassword ? 'Скрыть пароль' : 'Показать пароль'}
              onClick={() => setShowPassword((v) => !v)}
              className="absolute right-0 top-1/2 -translate-y-1/2 p-2 text-gray"
            >
              {showPassword ? (
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z" />
                  <circle cx="12" cy="12" r="3" />
                </svg>
              ) : (
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z" />
                  <circle cx="12" cy="12" r="3" />
                  <path d="M4 4l16 16" />
                </svg>
              )}
            </button>
          </div>

          {/* Забыли пароль? */}
          <div className="flex justify-end">
            <button
              type="button"
              className="text-[13px] leading-[120%] text-gray sm:text-[14px]"
              onClick={() => { /* TODO */ }}
            >
              Забыли пароль?
            </button>
          </div>

          {/* Кнопка */}
          <button
            type="submit"
            disabled={!isFormValid}
            className={`h-11 w-full rounded-full text-[15px] font-medium transition-colors sm:h-12 sm:text-[16px]
              ${isFormValid
                ? 'bg-accent text-black'
                : 'cursor-not-allowed bg-gray/50 text-primary'}`}
          >
            Получить код
          </button>
        </form>

        {/* Условия */}
        <p className="mt-6 text-center text-[11px] leading-[120%] text-gray sm:mt-8 sm:text-[12px]">
          Продолжая, я принимаю условия
          <br />
          <button
            type="button"
            className="mt-1 text-[13px] font-medium text-black sm:text-[14px]"
            onClick={() => { /* TODO */ }}
          >
            Политики конфиденциальности
          </button>
        </p>

        {/* Футер */}
        <p className="mt-auto pb-1 pt-3 text-center text-[13px] leading-[120%] text-gray sm:text-[14px]">
          Нет аккаунта?{' '}
          <button
            type="button"
            className="text-black"
            onClick={() => navigate('/register')}
          >
            Зарегистрироваться
          </button>
        </p>
      </div>
    </div>
  );
};

export default Auth;
